package com.example

import com.example.ExamQuestionHelper.QSpec

internal object GeographyLiveExamDisastersBank {
  private fun q(t: String, s: String, c: String, d1: String, d2: String, d3: String, e: String) =
    QSpec(t, s, c, listOf(d1, d2, d3), e)

  fun environmentAndDisasterQuestions(): List<QSpec> {
    val t = "පාරිසරික ගැටලු හා ආපදා කළමනාකරණය"
    return listOf(
      q(t, "'උපද්‍රවය' (Hazard) සහ 'ආපදාව' (Disaster) යන සංකල්ප දෙක අතර පවතින මූලික භූගෝලීය වෙනස කුමක්ද?",
        "උපද්‍රවය යනු හානි කළ හැකි විභව ස්වාභාවික/මානව සිදුවීමක් (උදා: ජනශූන්‍ය තැනක භූමිකම්පාවක්) වන අතර, එය අවදානමට ලක්විය හැකි මානව ප්‍රජාවකට බලපා සාමාන්‍ය ජීවිතය අඩාල කළ විට 'ආපදාවක්' බවට පත්වේ", "දෙකම සම්පූර්ණයෙන් එකම වේ", "ආපදාව සැමවිටම සුළු සිදුවීමකි", "උපද්‍රවය නගර තුළ පමණක් සිදුවේ",
        "ආපදා අවදානම = (උපද්‍රවය × අනාවරණය × අවදානමට ලක්වීමේ ප්‍රවණතාව) / ඔරොත්තු දීමේ හැකියාව ලෙස දැක්වේ."),
      q(t, "ස්වාභාවික උපද්‍රව (Natural Hazards) ප්‍රධාන වශයෙන් 'භූගර්භ විද්‍යාත්මක (Geological)' හා 'ජල-කාලගුණ විද්‍යාත්මක (Hydro-meteorological)' ලෙස බෙදූ විට භූගර්භ උපද්‍රවයකට නිදසුනක් කුමක්ද?",
        "භූමිකම්පා, ගිනිකඳු විදාරණ සහ සුනාමි", "නිවර්තන සුළි කුණාටු", "නියඟය", "අධික තාප තරංග (Heatwaves)",
        "ගංවතුර, සුළි කුණාටු, නියඟ හා නායයෑම් (වර්ෂාපතනය ආශ්‍රිත) බොහෝ විට ජල-කාලගුණ විද්‍යාත්මක උපද්‍රව කාණ්ඩයට අයත් වේ."),
      q(t, "ශ්‍රී ලංකාවේ ප්‍රධාන වශයෙන් කාලගුණික ආපදා අතර 'නිරිතදිග මෝසම් හා අන්තර් මෝසම්' කාලවලදී බහුලව ඇතිවන ආපදා දෙක මොනවාද?",
        "ගංවතුර (Floods) සහ නායයෑම් (Landslides)", "ගිනිකඳු විදාරණ හා හිම කුණාටු", "ප්‍රබල භූමිකම්පා", "හිම කඳු කඩා වැටීම්",
        "රත්නපුර, කෑගල්ල, කළුතර, ගාල්ල, මාතර, මහනුවර, නුවරඑළිය, බදුල්ල හා මාතලේ දිස්ත්‍රික්ක නායයෑම් අධි-අවදානම් කලාප ලෙස හඳුනාගෙන ඇත."),
      q(t, "ශ්‍රී ලංකාවේ නායයෑම් පූර්ව අනතුරු ඇඟවීම් නිකුත් කිරීම හා බෑවුම් ස්ථායීතාව පරීක්ෂා කිරීම භාර ප්‍රධාන රාජ්‍ය විද්‍යාත්මක ආයතනය කුමක්ද?",
        "ජාතික ගොඩනැගිලි පර්යේෂණ සංවිධානය (NBRO - National Building Research Organisation)", "වාරිමාර්ග දෙපාර්තමේන්තුව පමණක්", "මිනින්දෝරු දෙපාර්තමේන්තුව", "වනජීවී සංරක්ෂණ දෙපාර්තමේන්තුව",
        "පැය 24 ක් තුළ මි.මී. 75, 100 හෝ 150 ඉක්මවන වර්ෂාපතනයක් ලැබුණු විට NBRO ආයතනය කහ, තැඹිලි හා රතු නිවේදන නිකුත් කරයි."),
      q(t, "කඳුකර ප්‍රදේශවල 'නායයෑමක පූර්ව ලක්ෂණ' (Early Warning Signs of Landslides) ලෙස ජනතාව වහාම අවධානය යොමු කළ යුතු සංඥා මොනවාද?",
        "පොළොවේ හෝ නිවාස බිත්තිවල අලුතින් පැලීම් ඇතිවීම, ගස් හා විදුලි කණු ඇලවීම, වසන්ත උල්පත් හදිසියේ බොර වීම හෝ සිඳී යාම සහ පොළොවෙන් අමුතු ශබ්ද ඇසීම", "අහස නිල් පැහැති වීම", "සුළඟ නැවතීම", "මල් පිපීම",
        "මෙවැනි ලක්ෂණ දුටු වහාම රාත්‍රී නින්දට පෙර ආරක්ෂිත ස්ථාන වෙත ඉවත් වීම ජීවිත බේරා ගැනීමට තීරණාත්මකය."),
      q(t, "ශ්‍රී ලංකාවේ ඕනෑම හදිසි ආපදාවක් පිළිබඳව දැනුම් දීමට හා සහාය ලබා ගැනීමට 'ආපදා කළමනාකරණ මධ්‍යස්ථානය' (DMC) විසින් හඳුන්වා දී ඇති පැය 24 හදිසි ඇමතුම් අංකය කුමක්ද?",
        "117", "119", "1990", "1919",
        "117 මධ්‍යස්ථානය කාලගුණ විද්‍යා දෙපාර්තමේන්තුව, NBRO, වාරිමාර්ග දෙපාර්තමේන්තුව හා ත්‍රිවිධ හමුදාව සමඟ සම්බන්ධීකරණයෙන් කටයුතු කරයි."),
      q(t, "'ආපදා කළමනාකරණ චක්‍රයේ' (Disaster Management Cycle) ප්‍රධාන අදියර හතර නිවැරදි අනුපිළිවෙළින් දැක්වෙන්නේ කුමක්ද?",
        "අවම කිරීම (Mitigation) → පෙර සූදානම (Preparedness) → ප්‍රතිචාර දැක්වීම (Response) → යථා තත්ත්වයට පත් කිරීම (Recovery)", "විනාශ කිරීම → අමතක කිරීම → බලා සිටීම → පලා යාම", "ප්‍රතිචාර → හානිය → අවදානම → ආපදාව", "යථා තත්ත්වය → අවම කිරීම → පමාව → හානිය",
        "ආපදාවක් සිදුවීමට පෙර ක්‍රියාත්මක වන Mitigation සහ Preparedness මගින් ජීවිත හා දේපළ හානි විශාල ලෙස අඩු කළ හැකිය."),
      q(t, "'සෙන්ඩායි ආපදා අවදානම් අවම කිරීමේ රාමුව' (Sendai Framework 2015–2030) මගින් ලෝකයට ලබා දෙන ප්‍රධාන පණිවිඩය කුමක්ද?",
        "ආපදා සිදුවූ පසු සහන බෙදා දීමට වඩා, කලින්ම 'ආපදා අවදානම අවම කිරීම' (Disaster Risk Reduction - DRR) හා ඔරොත්තු දීමේ හැකියාව ගොඩනැගීම සඳහා ආයෝජනය කිරීම", "ආපදා පසු සහන පමණක් දීම", "පූර්ව අනතුරු ඇඟවීම් නැවැත්වීම", "වරාය තුළ නගර සෑදීම",
        "'වඩා හොඳින් යළි ගොඩනැගීම' (Build Back Better) යන්න මෙහි ප්‍රධාන ප්‍රමුඛතාවකි."),
      q(t, "'සුනාමි' (Tsunami) රළක් සාමාන්‍යයෙන් ජනනය වන්නේ කුමන සාගර පතුලේ සිදුවන ක්‍රියාවලියක් නිසාද?",
        "මුහුදු පතුලේ සිදුවන ප්‍රබල භූමිකම්පා (සිරස් භූ තැටි විස්ථාපනය), දිය යට ගිනිකඳු පිපිරීම් හෝ මුහුදු පතුලේ නායයෑම්", "සාමාන්‍ය මුහුදු සුළං හැමීම", "වඩදිය බාදිය", "ධීවර බෝට්ටු ගමන් කිරීම",
        "2004 දෙසැම්බර් 26 ඉන්දියානු සාගර සුනාමිය සුමාත්‍රා වෙරළට ඔබ්බෙන් ඇති වූ රිච්ටර් මාපක 9.1–9.3 ක භූමිකම්පාවකින් ජනිත විය."),
      q(t, "ගැඹුරු සාගරයේ සිට නොගැඹුරු වෙරළට ළඟා වන විට සුනාමි තරංගයේ හැසිරීම වෙනස් වන්නේ කෙසේද?",
        "ගැඹුරු සාගරයේදී පැයට කි.මී. 800+ වේගයෙන් ඉතා අඩු උසකින් ගමන් කරන අතර, වෙරළ අසල නොගැඹුරු ජලයේදී වේගය අඩු වී තරංගයේ උස මීටර් ගණනාවක් ඉහළ නැගීම (Shoaling)", "වෙරළ අසලදී තරංගය අතුරුදහන් වේ", "ගැඹුරු මුහුදේදී මීටර් 30 ක් උසය", "වෙරළේදී වේගය දෙගුණ වේ",
        "සුනාමියට පෙර මුහුදු ජලය අසාමාන්‍ය ලෙස පසුපසට ඇදී යාම (Drawback) ක්ෂණිකව උස් බිමකට පලා යා යුතු පූර්ව ස්වාභාවික සංඥාවකි."),
      q(t, "2004 සුනාමි ව්‍යසනයෙන් පසු ඉන්දියානු සාගර කලාපයේ රටවල් ආරක්ෂා කිරීමට පිහිටුවන ලද ජාත්‍යන්තර පද්ධතිය කුමක්ද?",
        "ඉන්දියානු සාගර සුනාමි පූර්ව අනතුරු ඇඟවීමේ හා අවම කිරීමේ පද්ධතිය (IOTWMS - DART බෝයා හා භූ කම්පන සංවේදක ජාලය)", "සහරා කාන්තාර පද්ධතිය", "උතුරු ඇමෙරිකානු හිම මධ්‍යස්ථානය", "යුරෝපා ගිනිකඳු ජාලය",
        "ශ්‍රී ලංකාවේ වෙරළ තීරය දිගේ 'සුනාමි පූර්ව අනතුරු ඇඟවීමේ කුළුණු' (Early Warning Towers) ස්ථාපිත කර ඇත."),
      q(t, "නාගරික ප්‍රදේශවල (උදා: කොළඹ, මහනුවර, ගම්පහ) කෙටි කාලීන තද වැස්සකින් පසුව පවා 'ක්ෂණික නාගරික ගංවතුර' (Urban Flash Floods) ඇතිවීමට ප්‍රධාන මානව හේතුව කුමක්ද?",
        "තෙත් බිම් හා පහත් බිම් ගොඩකර ගොඩනැගිලි තැනීම, කොන්ක්‍රීට්/තාර නිසා ජලය පොළොවට උරා නොගැනීම සහ කාණු පද්ධති ප්ලාස්ටික් හා රොන්මඩවලින් අවහිර වීම", "වෘක්ෂලතා අධික වීම", "තෙත් බිම් විශාල වීම", "වර්ෂාපතනය බින්දුව වීම",
        "නාගරික ගංවතුර පාලනය සඳහා 'ස්පොන්ජ් නගර' (Sponge Cities - උදා: බැද්දගාන තෙත් බිම් උද්‍යානය වැනි රැඳවුම් උද්‍යාන) සංකල්පය භාවිත කෙරේ."),
      q(t, "'හරිතාගාර ආචරණය' (Greenhouse Effect) සහ 'වැඩි දියුණු කළ හරිතාගාර ආචරණය' (Enhanced Greenhouse Effect / Global Warming) අතර වෙනස කුමක්ද?",
        "ස්වාභාවික හරිතාගාර ආචරණය පෘථිවියේ උෂ්ණත්වය ~15°C ක ජීවයට හිතකර මට්ටමක තබා ගන්නා අතර, මානව ක්‍රියාකාරකම් නිසා CO2, CH4 හා N2O වැඩිවීමෙන් අතිරික්ත තාපය සිරවී ගෝලීය උණුසුම ඉහළ යාම වැඩි දියුණු කළ ආචරණයයි", "ස්වාභාවික හරිතාගාර ආචරණය පෘථිවිය -18°C දක්වා සිසිල් කරයි", "දෙකම මුළුමනින්ම හානිකරය", "CO2 හරිතාගාර වායුවක් නොවේ",
        "ස්වාභාවික හරිතාගාර ආචරණය නොතිබුණේ නම් පෘථිවියේ සාමාන්‍ය උෂ්ණත්වය -18°C පමණ වී ජලය මිදී පවතිනු ඇත."),
      q(t, "ප්‍රධාන හරිතාගාර වායු අතර 'මීතේන්' (Methane - CH4) වායුව කාබන් ඩයොක්සයිඩ් (CO2) ට වඩා භයානක වන්නේ ඇයි සහ එහි ප්‍රධාන ප්‍රභව මොනවාද?",
        "වසර 100 ක පරිමාණයෙන් CO2 ට වඩා 28–30 ගුණයක තාප රඳවා ගැනීමේ බලයක් ඇති අතර එය ගවයන් වැනි සත්ත්ව පාලනය, වී වගා බිම්, කසළ කඳු දිරාපත් වීම හා ස්වාභාවික වායු කාන්දුවලින් පිටවේ", "එය ශාකවලින් පමණක් පිටවේ", "එය තාපය රඳවා නොගනී", "එය ඕසෝන් ස්තරය සාදයි",
        "කෙසේ වෙතත් මීතේන් වායුගෝලයේ රැඳී සිටින කාලය (~අවුරුදු 12) CO2 ට වඩා කෙටි බැවින් එය පාලනය කිරීමෙන් ඉක්මන් ප්‍රතිඵල ලැබේ."),
      q(t, "'අම්ල වැසි' (Acid Rain - pH අගය 5.6 ට අඩු) ඇති වීමට ප්‍රධාන වශයෙන් හේතු වන කාර්මික හා රථවාහන වායු දූෂක දෙක මොනවාද?",
        "සල්ෆර් ඩයොක්සයිඩ් (SO2) සහ නයිට්‍රජන් ඔක්සයිඩ් (NOx)", "ඔක්සිජන් සහ නයිට්‍රජන්", "හීලියම් සහ ආගන්", "ජල වාෂ්ප පමණක්",
        "අම්ල වැසි නිසා විල්වල මසුන් මිය යාම, වනාන්තර කොළ හැලීම, පස නිසරු වීම සහ හුණුගල්/මාබල් ස්මාරක (උදා: ටජ් මහල) ඛාදනය වීම සිදුවේ."),
      q(t, "පොළොවට එන හානිකර පාරජම්බුල කිරණ (UV-B) පෙරා හරින අපරිවර්තී ගෝලයේ (Stratosphere) පිහිටි 'ඕසෝන් ස්තරය' (Ozone Layer) සිදුරු වීමට හේතු වූ ප්‍රධාන රසායනික ද්‍රව්‍ය කුමක්ද?",
        "ශීතකරණ, වායු සමීකරණ හා ස්ප්‍රේ කෑන්වල භාවිත කළ ක්ලෝරෝෆ්ලෝරෝකාබන් (CFC) හා හෙලෝන් වායු", "කාබන් මොනොක්සයිඩ් පමණක්", "නයිට්‍රජන් වායුව", "මිරිදිය ජල වාෂ්ප",
        "1987 'මොන්ට්‍රියල් සන්ධානය' (Montreal Protocol) මගින් CFC තහනම් කිරීම නිසා ඕසෝන් ස්තරය දැන් ක්‍රමයෙන් සුව වෙමින් පවතී."),
      q(t, "1987 දී අත්සන් කළ 'මොන්ට්‍රියල් සන්ධානය' (Montreal Protocol) හා 2015 දී අත්සන් කළ 'පැරිස් ගිවිසුම' (Paris Agreement) අතර ප්‍රධාන අරමුණු වෙනස කුමක්ද?",
        "මොන්ට්‍රියල් සන්ධානය ඕසෝන් ස්තරය විනාශ කරන CFC වැනි ද්‍රව්‍ය තහනම් කිරීම සඳහා වන අතර, පැරිස් ගිවිසුම ගෝලීය උෂ්ණත්වය ඉහළ යාම 1.5°C–2°C ට අඩුවෙන් තබා ගැනීමට හරිතාගාර වායු අඩු කිරීම සඳහාය", "දෙකම ප්ලාස්ටික් භාවිතය වැඩි කිරීමටය", "පැරිස් ගිවිසුම ඕසෝන් සිදුර විශාල කිරීමටය", "දෙකම න්‍යෂ්ටික අවි පිළිබඳ ගිවිසුම් වේ",
        "මොන්ට්‍රියල් සන්ධානය ඉතිහාසයේ වඩාත්ම සාර්ථක ජාත්‍යන්තර පාරිසරික ගිවිසුම ලෙස සැලකේ."),
      q(t, "නාගරික වායු දූෂණයේදී 'ප්‍රකාශ රසායනික දුමාරය' (Photochemical Smog) නිර්මාණය වන්නේ කෙසේද?",
        "වාහන දුමෙන් පිටවන නයිට්‍රජන් ඔක්සයිඩ් හා වාෂ්පශීලී කාබනික සංයෝග (VOCs) තද හිරු එළිය සමඟ ප්‍රතික්‍රියා කර බිම් මට්ටමේ ඕසෝන් (Ground-level Ozone) හා විෂ දුමාරයක් සෑදීමෙන්", "හිම පතනය හා සීතල සුළං නිසා", "ගස් වැඩිපුර සිටුවීම නිසා", "වැසි වලාකුළු නිසා",
        "උස් අපරිවර්තී ගෝලයේ ඕසෝන් 'හොඳ ඕසෝන්' වන අතර පොළොව මට්ටමේ ඕසෝන් පෙනහළුවලට හානි කරන 'නරක ඕසෝන්' වේ."),
      q(t, "වායු ගුණාත්මක දර්ශකයේදී (AQI) මනිනු ලබන 'PM2.5' අංශු (විෂ්කම්භය මයික්‍රොමීටර 2.5 ට අඩු) සෞඛ්‍යයට අතිශය භයානක වන්නේ ඇයි?",
        "ඒවා මිනිස් කෙස් ගසකට වඩා 30 ගුණයකින් කුඩා බැවින් නාසයේ පෙරහන් පසුකර පෙනහළු ගැඹුරට හා රුධිර සංසරණ පද්ධතියටම ඇතුළු වී හෘද හා ශ්වසන රෝග ඇති කරන බැවින්", "ඒවා කිලෝග්‍රෑම් 1 ක් බර නිසා", "පෙනහළුවලට ඇතුළු නොවන නිසා", "ඔක්සිජන් නිපදවන නිසා",
        "ඩීසල් වාහන දුම, ගල් අඟුරු බලාගාර, අපද්‍රව්‍ය පිළිස්සීම හා ඉදිකිරීම් දූවිලි PM2.5 ප්‍රධාන ප්‍රභව වේ."),
      q(t, "ජල දූෂණයේදී කෘෂිකාර්මික පොහොර (නයිට්‍රේට් හා පොස්පේට්) හා අපජලය වැව්වලට ගලා යාමෙන් සිදුවන 'සුපෝෂණය' (Eutrophication) නිසා මසුන් මිය යන්නේ කෙසේද?",
        "අතිරික්ත පෝෂක නිසා ඇල්ගී ශාක අධිකව වර්ධනය වී (Algal Bloom) ජලය මත ආවරණයක් සෑදී, එම ඇල්ගී මිය ගොස් බැක්ටීරියා මගින් දිරාපත් වීමේදී ජලයේ දියවූ ඔක්සිජන් සියල්ල වැය වී 'මළ කලාප' (Dead Zones) බිහි වීමෙන්", "ජලයේ ඔක්සිජන් 10 ගුණයකින් වැඩි වීමෙන්", "ජලය හිම බවට පත් වීමෙන්", "මසුන්ට ආහාර වැඩි වීමෙන්",
        "බේරේ වැව, මහනුවර වැව හා කැලණි/බොල්ගොඩ පද්ධති ආශ්‍රිතව මෙවැනි ජල දූෂණ අවදානම් නිරීක්ෂණය වී ඇත."),
      q(t, "'ජෛව සමුච්චනය හා ජෛව විශාලනය' (Bioaccumulation & Biomagnification) මගින් පරිසර දූෂක ආහාර දාමයට බලපාන්නේ කෙසේද?",
        "DDT කෘමිනාශක, රසදිය (Mercury) හා ක්ෂුද්‍ර ප්ලාස්ටික් වැනි නොදිරන විෂ ද්‍රව්‍ය ප්ලවාංග සිට කුඩා මසුන්ටත්, ඉන්පසු විශාල මසුන් හා මිනිසුන්ටත් යන විට සෑම පෝෂණ මට්ටමකදීම සාන්ද්‍රණය වැඩි වීම", "ඉහළ පෝෂණ මට්ටම්වලදී විෂ සම්පූර්ණයෙන් නැති වීම", "ශාකවල පමණක් විෂ රැඳීම", "විෂ ජලයේ දියවී අතුරුදහන් වීම",
        "ජපානයේ මිනමාටා රෝගය (රසදිය විෂවීම) ජෛව විශාලනයේ ඛේදනීය ඓතිහාසික නිදසුනකි."),
      q(t, "'ඉලෙක්ට්‍රොනික අපද්‍රව්‍ය' (E-waste - පැරණි ජංගම දුරකථන, පරිගණක, බැටරි, TV) සාමාන්‍ය කසළ සමඟ පිළිස්සීම හෝ පොළොවේ වැළලීම අතිශය භයානක වන්නේ ඇයි?",
        "ඒවායේ ඊයම් (Lead), රසදිය, කැඩ්මියම්, ආසනික් හා ගිනි නිවන විෂ රසායනික අඩංගු බැවින් භූගත ජලය හා වාතය දිගුකාලීනව විෂ වන බැවින්", "ඒවා ඉතා හොඳ කාබනික පොහොර නිසා", "පැයකින් දිරාපත් වන නිසා", "ගස් වැඩීම වේගවත් කරන නිසා",
        "E-waste නිසි ප්‍රතිචක්‍රීකරණ ආයතන වෙත භාර දීමෙන් රන්, රිදී, තඹ හා දුර්ලභ ලෝහද නැවත ලබාගත හැකිය."),
      q(t, "'ක්ෂුද්‍ර ප්ලාස්ටික්' (Microplastics - මි.මී. 5 ට කුඩා ප්ලාස්ටික් කැබලි) සාගර පරිසරයට හා මිනිස් සිරුරට ඇතුළු වන්නේ කෙසේද?",
        "සාගරයට එක්වන ප්ලාස්ටික් බෝතල්/බෑග් හිරු එළියෙන් හා රළ පහරින් කුඩා කැබලිවලට කැඩීමෙන්, කෘත්‍රිම රෙදි සේදීමේදී ගැලවෙන කෙඳිවලින් හා ටයර් ගෙවීමෙන්", "ගල් පර්වත දිය වීමෙන්", "වැසි වලාකුළු වලින් ඉබේ සෑදීමෙන්", "මසුන් විසින් නිපදවීමෙන්",
        "2021 දී ශ්‍රී ලංකාවේ බටහිර වෙරළට ඔබ්බෙන් සිදු වූ MV X-Press Pearl නෞකා අනතුරින් විශාල ප්ලාස්ටික් කැටිති (Nurdles) වෙරළට ගොඩ ගැසී දැඩි සාගර හානියක් සිදුවිය."),
      q(t, "'වන විනාශය' (Deforestation) ගෝලීය දේශගුණික විපර්යාසයට දෙයාකාරයකින්ම දායක වන්නේ කෙසේද?",
        "වනාන්තර කැපීමෙන් හා පිළිස්සීමෙන් ගස්වල ගබඩා වී තිබූ කාබන් වායුගෝලයට මුදා හැරෙන අතරම, අනාගතයේ CO2 අවශෝෂණය කිරීමට සිටින හරිත කාබන් අවශෝෂකයද (Carbon Sink) අහිමි වේ", "වන විනාශය පෘථිවිය සිසිල් කරයි", "CO2 ප්‍රමාණය අඩු කරයි", "වර්ෂාපතනය දෙගුණ කරයි",
        "ඇමසන් වනයේ වන විනාශය හා ඉන්දුනීසියාවේ පීට් වනාන්තර පිළිස්සීම ගෝලීය කාබන් විමෝචනයට ප්‍රධාන හේතුවකි."),
      q(t, "'කාන්තාරීකරණය' (Desertification) යන පාරිසරික ගැටලුව නිවැරදිවම නිර්වචනය කරන්නේ කුමක් ලෙසද?",
        "දේශගුණික විචල්‍යතා (නියඟය) හා අධික තෘණ කැවීම, වන විනාශය, වැරදි වාරි ක්‍රම වැනි මානව ක්‍රියාකාරකම් නිසා ශුෂ්ක, අර්ධ-ශුෂ්ක හා වියළි උප-ආර්ද්‍ර ඉඩම්වල පාංශු සාරවත් බව පිරිහී නිසරු වීම", "සහරා කාන්තාරය සාගරයට ගිලී යාම", "නගරයක වැලි ක්‍රීඩා පිටියක් සෑදීම", "නිවර්තන වැසි වනාන්තර වැඩි වීම",
        "අප්‍රිකාවේ 'මහා හරිත පවුර' (Great Green Wall) ව්‍යාපෘතිය සහෙල් කලාපයේ කාන්තාරීකරණය නැවැත්වීමේ දැවැන්ත උත්සාහයකි."),
      q(t, "භූමිකම්පාවක ප්‍රබලතාව හා හානිය මැනීම සඳහා භාවිත කරන 'රිච්ටර්/මොමන්ට් මැග්නිටියුඩ් පරිමාණය' (Moment Magnitude - Mw) සහ 'මර්කලි තීව්‍රතා පරිමාණය' (Modified Mercalli Intensity) අතර වෙනස කුමක්ද?",
        "Mw පරිමාණය භූමිකම්පාවේ නාභියෙන් මුදා හැරුණු සැබෑ භෞතික ශක්තිය මනින අතර මර්කලි පරිමාණය එක් එක් ස්ථානයේදී මිනිසුන්ට දැනුණු ප්‍රමාණය හා ගොඩනැගිලි හානිය මනී", "දෙකම සුළං වේගය මනී", "මර්කලි පරිමාණය ගිනිකඳු උස මනී", "රිච්ටර් පරිමාණය වර්ෂාව මනී",
        "රිච්ටර්/මොමන්ට් පරිමාණයේ එක් පූර්ණ සංඛ්‍යාවකින් (උදා: 6 සිට 7 දක්වා) ශක්තිය ~32 ගුණයකින් වැඩි වේ."),
      q(t, "භූමිකම්පාවක 'නාභිය' (Focus / Hypocenter) සහ 'අපිකේන්ද්‍රය' (Epicenter) යන ස්ථාන දෙක හඳුනා ගන්නේ කෙසේද?",
        "නාභිය යනු පොළොව අභ්‍යන්තරයේ පාෂාණ බිඳී භූමිකම්පාව ආරම්භ වන සැබෑ ස්ථානය වන අතර අපිකේන්ද්‍රය යනු නාභියට කෙලින්ම ඉහළින් පෘථිවි පෘෂ්ඨයේ පිහිටි ස්ථානයයි", "අපිකේන්ද්‍රය මුහුදු පතුලට කි.මී. 500 ක් යට පිහිටයි", "නාභිය අහසේ පිහිටයි", "දෙකම එකම ස්ථානයේ නොවේ, සමහර විට කි.මී. 1,000 ක් ඈතින් පිහිටයි",
        "සාමාන්‍යයෙන් අපිකේන්ද්‍රය අසලදී භූමිකම්පා හානිය වැඩි වන අතර නොගැඹුරු නාභි (Shallow Focus) භූමිකම්පා වඩාත් විනාශකාරී වේ."),
      q(t, "ජපානයේ හා චිලී රාජ්‍යයේ ඉතා ප්‍රබල භූමිකම්පා ඇති වුවද ජීවිත හානි ඉතා අඩු මට්ටමක තබා ගැනීමට සමත් වී ඇත්තේ කුමන ආපදා අවම කිරීමේ පියවර නිසාද?",
        "දැඩි භූ-කම්පන ප්‍රතිරෝධී ගොඩනැගිලි නීති (Seismic Building Codes), Base Isolation කම්පන අවශෝෂක, ස්වයංක්‍රීය දුම්රිය/ගෑස් නැවැත්වීමේ පද්ධති හා පාසල් මට්ටමේ නිරන්තර පෙරහුරු", "සියලු නගර හිස් කිරීමෙන්", "ගඩොල් හා මැටිවලින් පමණක් ගොඩනැගීමෙන්", "භූමිකම්පා වළක්වන යන්ත්‍ර මගින්",
        "'මිනිසුන් මරන්නේ භූමිකම්පා නොවේ, දුර්වල ගොඩනැගිලිය' යන්න ආපදා කළමනාකරණයේ ප්‍රසිද්ධ කියමනකි."),
      q(t, "'නාගරික තාප දූපත' (Urban Heat Island - UHI) යන පාරිසරික ගැටලුව ඇතිවීමට ප්‍රධාන හේතුව කුමක්ද?",
        "නගරවල අඳුරු තාර මාර්ග, කොන්ක්‍රීට් ගොඩනැගිලි, වාහන/AC තාපය හා ගස් කොළන් අඩු වීම නිසා අවට ග්‍රාමීය ප්‍රදේශවලට වඩා නගරයේ උෂ්ණත්වය 2°C–5°C කින් ඉහළ යාම", "නගරවල වැඩිපුර ගස් තිබීම", "නගරවල වැඩිපුර වැව් තිබීම", "හිම පතනය වැඩි වීම",
        "නාගරික වන වගා (Urban Forestry), සෙවණ මාර්ග, සුදු පැහැති සිසිල් වහලවල් (Cool Roofs) හා හරිත බිත්ති මගින් මෙම උණුසුම අඩු කළ හැකිය."),
      q(t, "ශ්‍රී ලංකාවේ බරපතල සමාජ-පාරිසරික ගැටලුවක් බවට පත්ව ඇති 'අලි-මිනිස් ගැටුම' (Human-Elephant Conflict - HEC) ඇතිවීමට ප්‍රධානම භූගෝලීය හේතුව කුමක්ද?",
        "වන අලි සාම්ප්‍රදායිකව ගමන් කළ වන මංකඩ (Elephant Corridors) හා වාසභූමි අවහිර කරමින් අනවසර වගා බිම්, ජනාවාස හා සංවර්ධන ව්‍යාපෘති ව්‍යාප්ත වීම", "අලි ජලය බීම නැවැත්වීම", "මුහුදු මට්ටම ඉහළ යාම", "වනාන්තර ප්‍රමාණය දෙගුණ වීම",
        "වන අලි රක්ෂිත අතර ස්වාභාවික වන මංකඩ නැවත විවෘත කිරීම, විද්‍යුත් වැටවල් නිසි නඩත්තුව හා අලි ගමන් කළ හැකි උමං/පාලම් ඉදිකිරීම තිරසාර විසඳුම් වේ."),
      q(t, "'ආක්‍රමණශීලී ආගන්තුක ජීවීන්' (Invasive Alien Species - උදා: ජපන් ජබර, සැල්වීනියා, ගඳපාන, කටුපිල, ටැංකි සුද්දා මාලුවා) පරිසර පද්ධතිවලට තර්ජනයක් වන්නේ ඇයි?",
        "ස්වාභාවික සතුරන් නොමැති නව පරිසරයක වේගයෙන් බෝ වී දේශීය හා ආවේණික ශාක හා සත්ත්ව විශේෂ යටපත් කර ජල මාර්ග හා වනාන්තර විනාශ කරන බැවින්", "දේශීය ජීවීන් ආරක්ෂා කරන නිසා", "ජෛව විවිධත්වය දස ගුණයකින් වැඩි කරන නිසා", "පැය කිහිපයකින් මිය යන නිසා",
        "නොදැනුවත්ව හෝ විසිතුරු සතුන්/ශාක ලෙස ගෙන්වා පරිසරයට මුදා හැරීම මෙම ගැටලුවට ප්‍රධාන හේතුවයි."),
      q(t, "'නියඟය' (Drought) අනෙකුත් ක්ෂණික ආපදාවලින් වෙනස්ව 'සෙමින් ඇරඹෙන ආපදාවක්' (Slow-onset Disaster) ලෙස හඳුන්වන්නේ ඇයි?",
        "එය භූමිකම්පාවක් මෙන් තත්පර ගණනකින් නොව සති හා මාස ගණනක් පුරා වර්ෂාපතනය අඩු වෙමින් ගොස් කෘෂිකර්මය, පානීය ජලය හා ජල විදුලියට දීර්ඝකාලීන හානි සිදු කරන බැවින්", "එය මිනිත්තුවකින් අවසන් වන නිසා", "එය සාගරයේ පමණක් සිදුවන නිසා", "එයින් කිසිදු බලපෑමක් නැති නිසා",
        "කාලගුණ විද්‍යාත්මක, කෘෂිකාර්මික, ජල විද්‍යාත්මක හා සමාජ-ආර්ථික නියඟ ලෙස එහි අදියර හතරක් හඳුනාගනී."),
      q(t, "'කාලගුණික නියඟ අවම කිරීමේදී' ශ්‍රී ලංකාවේ පුරාණ රජවරුන් විසින් නිර්මාණය කළ 'එල්ලංගා වැව් පද්ධතිය' (Cascading Tank System) අදටත් විශිෂ්ට වන්නේ ඇයි?",
        "නිම්නයේ ඉහළ සිට පහළට දම්වැලක් සේ සම්බන්ධ වූ කුඩා හා මධ්‍යම වැව් මගින් වැසි ජලය නාස්ති නොවී රඳවා භූගත ජලය පෝෂණය කර නියඟ කාලයේදී පරිසරය රැක ගන්නා බැවින්", "සියලු ජලය එකවර මුහුදට යවන නිසා", "ජලය වාෂ්ප කරන නිසා", "කඳු මුදුන්වල ඉදිකර ඇති නිසා",
        "FAO ආයතනය විසින් ශ්‍රී ලංකාවේ එල්ලංගා වැව් ගොවි පද්ධතිය 'ගෝලීය වශයෙන් වැදගත් කෘෂිකාර්මික උරුමයක්' (GIAHS) ලෙස නම් කර ඇත."),
      q(t, "'ලැව් ගිනි' (Wildfires) හටගැනීමට හා වේගයෙන් පැතිරීමට දායක වන ප්‍රධාන ස්වාභාවික හා මානව සාධක මොනවාද?",
        "දීර්ඝ නියඟ, අධික උණුසුම හා වියළි තද සුළං සමඟ කැලෑ එළි කිරීමට හෝ සතුන් දඩයම් කිරීමට මිනිසුන් ගිනි තැබීම", "අධික ධාරානිපාත වර්ෂාව", "අයිස් කුණාටු", "ඉහළ ආර්ද්‍රතාවය",
        "ශ්‍රී ලංකාවේ නකල්ස්, බදුල්ල, මොණරාගල හා පයිනස් වගා බිම්වල වියළි කාලයේදී මානව ගිනි තැබීම් නිසා ලැව් ගිනි බහුලව වාර්තා වේ."),
      q(t, "'කසළ කළමනාකරණයේ ධූරාවලිය' (Waste Management Hierarchy) අනුව වඩාත්ම ප්‍රමුඛත්වය දිය යුතු පළමු පියවර හා අවසාන පියවර පිළිවෙළින් කුමක්ද?",
        "පළමු ප්‍රමුඛතාව: අපද්‍රව්‍ය ජනනය වැළැක්වීම හා අවම කිරීම (Prevent / Reduce); අවසාන පියවර: ක්‍රමවත්ව බැහැර කිරීම (Sanitary Disposal/Landfill)", "පළමු පියවර: පිළිස්සීම; අවසාන පියවර: අවම කිරීම", "සියල්ල ගංගාවට දැමීම", "නැවත භාවිතය තහනම් කිරීම",
        "මීතොටමුල්ල කසළ කන්ද කඩා වැටීම විවෘත කසළ බැහැර කිරීමේ (Open Dumping) බරපතල අනතුර පෙන්වා දුන් ශ්‍රී ලාංකික ඛේදවාචකයකි."),
      q(t, "'නගර කසළ කඳු පිපිරීමට හා ගිනි ගැනීමට' ප්‍රධාන රසායනික හේතුව කුමක්ද?",
        "විවෘත කසළ ගොඩවල් ඇතුළත කාබනික අපද්‍රව්‍ය ඔක්සිජන් රහිතව දිරාපත් වීමෙන් ගිනි ගන්නා සුළු 'මීතේන් වායුව' (CH4) නිපදවී රැස්වීම", "කසළ තුළ හිම සෑදීම", "නයිට්‍රජන් වායුව සිසිල් වීම", "ඔක්සිජන් 100% පිරීම",
        "එබැවින් කාබනික අපද්‍රව්‍ය වෙන් කර කොම්පෝස්ට් හෝ ජීව වායුව (Biogas) නිපදවීම කසළ කඳු අවදානම නැති කරන ප්‍රධාන විසඳුමකි."),
      q(t, "'හරිතාගාර වායු විමෝචනය' අනුව 'ශුද්ධ ශූන්‍ය විමෝචනය' (Net-Zero Emissions) යන්නෙන් අදහස් කරන්නේ කුමක්ද?",
        "මානව ක්‍රියාකාරකම් මගින් වායුගෝලයට මුදා හරින හරිතාගාර වායු ප්‍රමාණය හැකිතාක් අවම කර, ඉතිරි කුඩා ප්‍රමාණය වනාන්තර හෝ කාබන් අවශෝෂක මගින් සමානව ඉවත් කර සමතුලිත කිරීම", "පෘථිවියේ සියලු කර්මාන්තශාලා 100% වැසීම", "කාබන් විමෝචනය දෙගුණ කිරීම", "සූර්ය බලය නැවැත්වීම",
        "දේශගුණික අර්බුදය පාලනය කිරීමට 2050 වන විට ගෝලීය Net-Zero ඉලක්කය සපුරා ගැනීමට රටවල් රැසක් ප්‍රතිඥා දී ඇත."),
      q(t, "'දේශගුණික විපර්යාස අවම කිරීම (Mitigation)' සහ 'දේශගුණික විපර්යාසවලට අනුවර්තනය වීම (Adaptation)' අතර වෙනස කුමක්ද?",
        "Mitigation යනු හරිතාගාර වායු අඩු කර උණුසුම් වීමේ මූල හේතුව නැවැත්වීම වන අතර, Adaptation යනු දැනටමත් සිදුවන මුහුදු මට්ටම ඉහළ යාම හා නියඟයට ඔරොත්තු දෙන ලෙස ගොවිතැන හා නගර හැඩගැස්වීමයි", "දෙකම එකම ක්‍රියාවලියකි", "Adaptation යනු තෙල් වැඩිපුර පිළිස්සීමයි", "Mitigation යනු වනාන්තර කැපීමයි",
        "ශ්‍රී ලංකාව ගෝලීය විමෝචනයෙන් 0.1% කටත් වඩා අඩු කොටසක් නිකුත් කළද දේශගුණික බලපෑම්වලට දැඩිව ගොදුරු වන බැවින් අනුවර්තනය (Adaptation) ඉතා වැදගත්ය."),
      q(t, "'තෘණ බිම් හා වෙරළබඩ කඩොලාන' 'නීල කාබන්' (Blue Carbon) පරිසර පද්ධති ලෙස හැඳින්වෙන්නේ ඇයි?",
        "කඩොලාන, ලුණු වගුරු (Salt Marshes) හා මුහුදු තෘණ (Seagrasses) ගොඩබිම් වනාන්තරවලට වඩා ඒකක වර්ගඵලයකින් කිහිප ගුණයක් වැඩි කාබන් ප්‍රමාණයක් මඩ සහිත පසෙහි සියවස් ගණනක් තැන්පත් කර ගන්නා බැවින්", "ඒවා නිල් පැහැති කොළ සහිත නිසා", "කාබන් වායුව නිපදවන නිසා", "ගැඹුරු සාගර පතුලේ වැඩෙන නිසා",
        "ශ්‍රී ලංකාව කඩොලාන පරිසර පද්ධති ආරක්ෂා කිරීමේ ජාත්‍යන්තර ගිවිසුම්වලට හා සංරක්ෂණ වැඩසටහන්වලට ප්‍රමුඛත්වය දී ඇත."),
      q(t, "'වෙරළ ඛාදනය' (Coastal Erosion) ස්වාභාවික මුහුදු රළට අමතරව මානව ක්‍රියාකාරකම් නිසා උග්‍ර වන්නේ කෙසේද?",
        "කොරල් පර කැඩීම, මුහුදු වැලි හා ගංගා වැලි අධිකව ගොඩදැමීම (වෙරළට ලැබෙන වැලි සැපයුම අඩුවීම) සහ වෙරළ තීරයේ වැලි කඳු හා කඩොලාන විනාශ කර ඉදිකිරීම් කිරීම", "කඩොලාන සිටුවීමෙන්", "ගංගා පිරිසිදු කිරීමෙන්", "කොරල් ආරක්ෂා කිරීමෙන්",
        "වෙරළ සංරක්ෂණ හා වෙරළ සම්පත් කළමනාකරණ දෙපාර්තමේන්තුව (CCD) ගල් වැටි (Revetments), තරංග කඩන (Breakwaters) හා කෘත්‍රිම වැලි පෝෂණය (Beach Nourishment) භාවිත කරයි."),
      q(t, "'නිවර්තන සුළි කුණාටුවකදී' (Cyclone) විශාලතම ජීවිත හා දේපළ විනාශය බොහෝ විට සිදුවන්නේ සුළඟින් පමණක් නොව කුමන සාගර සංසිද්ධිය නිසාද?",
        "කුණාටු උදම් රළ (Storm Surge) හෙවත් අඩු පීඩනය හා තද සුළං නිසා මුහුදු ජලය ගොඩබිම වෙත තල්ලු වී වෙරළබඩ ප්‍රදේශ යට වීම", "භූමිකම්පා ඇති වීම", "හිම දිය වීම", "වඩදිය අඩු වීම",
        "1978 මඩකලපුව සුළි කුණාටුව ශ්‍රී ලංකාවට දැඩි හානි සිදු කළ ඓතිහාසික නිවර්තන සුළි කුණාටුවකි."),
      q(t, "'පාරිසරික බලපෑම් තක්සේරුව' (EIA - Environmental Impact Assessment) නීතිමය වශයෙන් ක්‍රියාත්මක කරනු ලබන ශ්‍රී ලංකාවේ ප්‍රධාන ආයතනය කුමක්ද?",
        "මධ්‍යම පරිසර අධිකාරිය (CEA - Central Environmental Authority)", "මහ බැංකුව", "තැපැල් දෙපාර්තමේන්තුව", "විභාග දෙපාර්තමේන්තුව",
        "ජාතික පාරිසරික පනත යටතේ නියමිත මහා පරිමාණ ව්‍යාපෘති සඳහා අනුමැතිය ලබා ගැනීමට මහජන අදහස් විමසීමද EIA ක්‍රියාවලියට අයත් වේ."),
      q(t, "'ගංවතුර ආපදා අවම කිරීමේදී ව්‍යුහාත්මක (Structural)' හා 'ව්‍යුහාත්මක නොවන (Non-structural)' පියවර අතර නිවැරදි උදාහරණ යුගලය කුමක්ද?",
        "ව්‍යුහාත්මක: ගං ඉවුරු බැමි (Levees) හා රැඳවුම් ජලාශ ඉදිකිරීම; ව්‍යුහාත්මක නොවන: ගංවතුර තැන්නේ ඉදිකිරීම් තහනම් කිරීමේ කලාපකරණය (Zoning), රක්ෂණය හා පූර්ව අනතුරු ඇඟවීම්", "දෙකම බැමි ඉදිකිරීමයි", "ව්‍යුහාත්මක නොවන යනු කිසිවක් නොකිරීමයි", "දෙකම අසාර්ථක ක්‍රම වේ",
        "ලාභදායී හා තිරසාර ආපදා කළමනාකරණයේදී මෙම ක්‍රම දෙකම සංයෝජනය කෙරේ."),
      q(t, "'ශ්‍රී ලංකාවේ ගංවතුර පූර්ව අනතුරු ඇඟවීම් හා ජලාශ වාන් දොරටු කළමනාකරණය' සිදු කරන ප්‍රධාන ආයතනය කුමක්ද?",
        "වාරිමාර්ග දෙපාර්තමේන්තුව (Irrigation Department - හා මහවැලි අධිකාරිය)", "රේගු දෙපාර්තමේන්තුව", "ආගමන විගමන දෙපාර්තමේන්තුව", "මෝටර් රථ ප්‍රවාහන දෙපාර්තමේන්තුව",
        "කැලණි, කළු, ගිං, නිල්වලා හා අත්තනගලු ඔය ජල මාපක දත්ත අනුව ගංවතුර මට්ටම් නිරන්තරයෙන් නිරීක්ෂණය කෙරේ."),
      q(t, "'ප්‍රජා මූලික ආපදා කළමනාකරණය' (Community-Based Disaster Risk Management - CBDRM) සාර්ථක ආපදා ප්‍රතිචාරයකට අත්‍යවශ්‍ය වන්නේ ඇයි?",
        "ඕනෑම ආපදාවකදී පළමු පැය කිහිපයේදී හමුදාව හෝ බාහිර සහන කණ්ඩායම් පැමිණීමට පෙර 'පළමු ප්‍රතිචාර දක්වන්නන්' (First Responders) වන්නේ එම ගමේම පුහුණු කළ ජනතාව බැවින්", "ප්‍රජාව ආපදා ගැන නොදන්නා නිසා", "බාහිර සහාය තත්පරයකින් පැමිණෙන නිසා", "ගැමියන්ට සහභාගී වීම තහනම් නිසා",
        "ග්‍රාම නිලධාරී වසම් මට්ටමින් ආපදා කළමනාකරණ කමිටු, ආරක්ෂිත ගමන් මාර්ග සිතියම් හා ප්‍රථමාධාර පුහුණුව ලබා දීම මෙහි අරමුණයි."),
      q(t, "'ස්වාභාවික විපතකදී ජලය මගින් බෝවන රෝග' (Water-borne Diseases - උදා: පාචනය, කොලරාව, හෙපටයිටිස් A, මී උණ/Leptospirosis) ගංවතුරට පසු පැතිරෙන්නේ ඇයි?",
        "වැසිකිළි වළවල් හා කසළ ගංවතුරට මිශ්‍ර වීමෙන් පානීය ළිං අපවිත්‍ර වීමත් මී මුත්‍රා මිශ්‍ර මඩ ජලයේ ජනතාව ගැවසීමත් නිසා", "ජලය ඉතා පිරිසිදු වන නිසා", "මදුරුවන් අතුරුදහන් වන නිසා", "වැසි ජලය නටන උණුසුමේ ඇති නිසා",
        "ගංවතුර බැස ගිය පසු ළිං පිරිසිදු කර ක්ලෝරීන් යෙදීමත්, ජලය උතුරුවා පානය කිරීමත් අත්‍යවශ්‍ය සෞඛ්‍ය පියවරකි."),
      q(t, "'නොදිරන කෘෂි රසායනික හා භූගත පානීය ජල දූෂණය' වැළැක්වීම සඳහා අපද්‍රව්‍ය හා පළිබෝධනාශක කළමනාකරණයේදී ගත යුතු ප්‍රධාන පියවර කුමක්ද?",
        "ඒකාබද්ධ පළිබෝධ කළමනාකරණය (IPM), කාබනික වගාව, නියමිත මාත්‍රාව පමණක් භාවිතය හා හිස් රසායනික බෝතල් ජල මූලාශ්‍රවල සේදීමෙන් වැළකීම", "බෝතල් ගංගාවට දැමීම", "දස ගුණයක් පළිබෝධනාශක ඉසීම", "ළිං තුළ රසායන දිය කිරීම",
        "ජල මූලාශ්‍ර හා රක්ෂිත ඉවුරු (Riparian Buffers) ගස් වැවීමෙන් රසායනික ගලා යාම පෙරා හරියි."),
      q(t, "'රැම්සා තෙත් බිම් සම්මුතිය' (Ramsar Convention on Wetlands - 1971) යටතේ ශ්‍රී ලංකාවේ බූන්දල, ආනවිලුන්දාව, මාදු ගඟ, කුමන, විල්පත්තු හා වන්කාලෙයි ආරක්ෂා කරන්නේ ඇයි?",
        "ජලජ පක්ෂීන්ගේ වාසභූමි, ගංවතුර අවශෝෂණය, ජල පිරිසිදු කිරීම හා වෙරළ ආරක්ෂාව සපයන ජාත්‍යන්තර වශයෙන් වැදගත් තෙත් බිම් ලෙස සංරක්ෂණය කිරීමට", "කර්මාන්තශාලා සඳහා ගොඩ කිරීමට", "වගුරු බිම් සිඳුවා දැමීමට", "කසළ පිරවීමට",
        "ශ්‍රී ලංකාවේ අගනුවර කොළඹ ලෝකයේ පළමු 'රැම්සා තෙත් බිම් නගරවලින්' (Ramsar Wetland City) එකක් ලෙසද පිළිගැනීමට ලක්ව ඇත."),
      q(t, "'හරිත පටි හා තිරසාර නගර සැලසුම්කරණය' (Sustainable Cities - SDG 11) යටතේ ගංවතුර හා තාප තරංග අවම කිරීමට ගත හැකි නාගරික පියවර මොනවාද?",
        "විනිවිද යන පදික වේදිකා (Permeable Pavements), වැව් හා ඇළ මාර්ග පුළුල් කිරීම, නාගරික උද්‍යාන වැඩි කිරීම සහ ගංවතුර අධි-අවදානම් කලාපවල ඉදිකිරීම් තහනම් කිරීම", "සියලු වැව් ගොඩ කිරීම", "කොන්ක්‍රීට් පමණක් දැමීම", "සියලු ගස් කපා දැමීම",
        "ස්වාභාවික ජල බැස්මට ඉඩ සැලසීම කොන්ක්‍රීට් බැමිවලට වඩා ලාභදායී හා ආරක්ෂිත වේ."),
      q(t, "'භූගර්භ විද්‍යාත්මක ආපදා අතර ද්‍රවීකරණය' (Soil Liquefaction) යනු භූමිකම්පාවකදී කුමන ස්ථානවල සිදුවන භයානක සංසිද්ධියක්ද?",
        "ජලයෙන් සංතෘප්ත වූ ලිහිල් වැලි සහිත පස භූමිකම්පා කම්පනය නිසා තාවකාලිකව ඝන ශක්තිය අහිමි වී දියර මඩක් මෙන් හැසිරී ගොඩනැගිලි ගිලා බැසීමට හෝ ඇල වීමට සැලැස්වීම", "ඝන ග්‍රැනයිට් පර්වත දිය වීම", "වලාකුළු ඝන වීම", "වැලි කාන්තාර ගල් වීම",
        "1964 නිගාටා (ජපානය) හා 2011 ක්‍රයිස්ට්චර්ච් (නවසීලන්තය) භූමිකම්පාවලදී මෙය දැඩි හානි ඇති කළේය."),
      q(t, "'ගිනිකඳු විදාරණයකදී' (Volcanic Eruption) ලාවා ගලා යාමටත් වඩා වේගවත් හා මාරාන්තික වන උපද්‍රව දෙක කුමක්ද?",
        "පයිරොක්ලාස්ටික් ප්‍රවාහ (Pyroclastic Flows - සෙල්සියස් 800°C+ උණුසුම් වායු හා අළු වලාකුළ) සහ ලාහාර් මඩ ගංවතුර (Lahars)", "සුළු ශබ්දය පමණක්", "සිසිල් වැස්ස", "සුදු හිම පතනය",
        "ලොව හිම මුදුන් සහිත ගිනිකඳු පිපිරෙන විට අයිස් දිය වී ගිනිකඳු අළු සමඟ මිශ්‍ර වී කොන්ක්‍රීට් මෙන් ගලා යන 'ලාහාර්' ඉතා භයානකය."),
      q(t, "'කාලගුණික ආන්තික සිදුවීම්' (Extreme Weather Events) අතර 'තාප තරංග' (Heatwaves) කෘෂිකර්මයට හා මිනිස් සෞඛ්‍යයට බලපාන්නේ කෙසේද?",
        "දින ගණනාවක් අසාමාන්‍ය අධික උෂ්ණත්වය පැවතීමෙන් විජලනය, තාප ආඝාතය (Heatstroke), විදුලි පරිභෝජන අධිබර වීම් හා බෝග මැලවී යාම සිදුවේ", "එමගින් හිම කැට වැටේ", "ජල සැපයුම දෙගුණ වේ", "පැළෑටි වේගයෙන් වැඩේ",
        "දේශගුණික විපර්යාස හේතුවෙන් ලොව පුරා තාප තරංගවල සංඛ්‍යාතය හා තීව්‍රතාව සීඝ්‍රයෙන් ඉහළ යමින් පවතී."),
      q(t, "'නියඟ හා ගංවතුර ආපදා කළමනාකරණයේදී ශ්‍රී ලංකාවේ කාලගුණ විද්‍යා දෙපාර්තමේන්තුව' ඉටු කරන ප්‍රධාන කාර්යභාරය කුමක්ද?",
        "රේඩාර්, චන්ද්‍රිකා හා කාලගුණ මධ්‍යස්ථාන දත්ත මගින් තද වැසි, අකුණු, තද සුළං, සුළි කුණාටු හා රළු මුහුදු ස්වභාවය පිළිබඳ පූර්ව අනතුරු ඇඟවීම් නිකුත් කිරීම", "ගංගා වේලි ඉදිකිරීම", "රෝහල් පාලනය", "ගොඩනැගිලි සැලසුම් අනුමත කිරීම",
        "ධීවරයන් හා නාවිකයන් මුහුදු යාමට පෙර කාලගුණ අනාවැකි හා රතු නිවේදන අනුගමනය කිරීම ජීවිතාරක්ෂාවට අත්‍යවශ්‍ය වේ."),
      q(t, "'අකුණු අනතුරු' (Lightning Hazards) ශ්‍රී ලංකාවේ වැඩිපුරම වාර්තා වන්නේ කුමන කාලගුණික කාලසීමාව තුළද?",
        "පළමු හා දෙවන අන්තර්-මෝසම් කාලවල (මාර්තු–අප්‍රේල් සහ ඔක්තෝබර්–නොවැම්බර්) සවස් කාලයේ ඇතිවන සංවහන ගිගුරුම් සහිත වැසි සමඟ", "ජනවාරි උදෑසන", "වියළි ජුනි මාසයේ", "මධ්‍යම රාත්‍රී සිසිල් සුළං සමඟ",
        "අකුණු ගසන විට විවෘත පිට්ටනි, උස් ගස් යට, ජලාශ තුළ හා රැහැන් සහිත විදුලි උපකරණ අසල රැඳීමෙන් වැළකී ගොඩනැගිල්ලක් හෝ සංවෘත වාහනයක් තුළට යා යුතුය."),
      q(t, "'සාගර ආම්ලීකරණය' (Ocean Acidification) යනු කුමක්ද සහ එය සමුද්‍ර පරිසර පද්ධතිවලට හානි කරන්නේ කෙසේද?",
        "වායුගෝලයේ අතිරික්ත CO2 වායුව සාගර ජලයේ දියවී කාබනික් අම්ලය සෑදීමෙන් මුහුදු ජලයේ pH අගය පහළ වැටී කොරල්, මුතු බෙල්ලන් හා කවච සහිත සතුන්ගේ කැල්සියම් කාබනේට් කවච දිය වී යාම", "මුහුදු ජලය සීනි රස වීම", "සාගරයේ pH අගය 14 දක්වා වැඩි වීම", "මාළුන්ට පිහිනීම පහසු වීම",
        "මෙය දේශගුණික විපර්යාසයේ 'දෙවන CO2 ගැටලුව' ලෙස හැඳින්වෙන අතර ධීවර කර්මාන්තයටද තර්ජනයකි."),
      q(t, "'තෙල් කාන්දු' (Marine Oil Spills) සාගර පරිසරයට ඇති කරන ක්ෂණික හා දිගුකාලීන හානි මොනවාද?",
        "ජලය මතුපිට තෙල් පටලයක් සෑදී හිරු එළිය හා ඔක්සිජන් හුවමාරුව අවහිර කිරීම, මුහුදු පක්ෂීන්ගේ පිහාටු ඇලී මිය යාම සහ කඩොලාන/මසුන් විෂ වීම", "ජලය පිරිසිදු වීම", "කොරල් වේගයෙන් වැඩීම", "පක්ෂීන්ට පිහිනීම පහසු වීම",
